fn resource_name<'a>(
    resource: &'a renderdocx::replay::ResourceInfo,
    renames: Option<&'a serde_json::Value>,
) -> &'a str {
    resource
        .rename_key
        .as_deref()
        .and_then(|key| renames.and_then(|doc| annotations::resource_name(doc, key).ok().flatten()))
        .unwrap_or(&resource.name)
}

