fn parse_debug_triplet(value: &str) -> Option<[u32; 3]> {
    let mut parts = value.split(',').map(|part| part.trim().parse::<u32>().ok());
    let result = [parts.next()??, parts.next()??, parts.next()??];
    if parts.next().is_some() {
        None
    } else {
        Some(result)
    }
}

fn parse_optional_debug_selector(value: &str) -> Result<Option<u32>, ()> {
    let value = value.trim();
    if value.is_empty() {
        return Ok(None);
    }
    value
        .parse::<u32>()
        .ok()
        .filter(|value| *value != u32::MAX)
        .map(Some)
        .ok_or(())
}

const SHADER_SOURCE_PAGE_LINES: usize = 200;

fn shader_source_page(contents: &str, page: usize) -> (usize, Vec<(usize, &str)>) {
    let total = contents.lines().count();
    let start = page.saturating_mul(SHADER_SOURCE_PAGE_LINES);
    let lines = contents
        .lines()
        .enumerate()
        .skip(start)
        .take(SHADER_SOURCE_PAGE_LINES)
        .map(|(line, text)| (line + 1, text))
        .collect();
    (total, lines)
}

fn collect_shader_debug(
    session: &Session,
    event: u32,
    context: ShaderDebugContext,
) -> Result<ShaderDebugView, String> {
    let stage = match context {
        ShaderDebugContext::Vertex { .. } => 0,
        ShaderDebugContext::Pixel(_) => 4,
        ShaderDebugContext::Compute(_) => 5,
        ShaderDebugContext::Mesh(_) => 7,
    };
    let shader = session.shader(stage, None)?;
    if shader.event_id != event {
        return Err("Shader response belongs to another event".into());
    }
    let trace = match context {
        ShaderDebugContext::Vertex {
            vertex,
            instance,
            index,
            view,
        } => session.debug_vertex(vertex, instance, index, view)?,
        ShaderDebugContext::Pixel(selection) => session.debug_pixel(selection)?,
        ShaderDebugContext::Compute(selection) => session.debug_compute(selection)?,
        ShaderDebugContext::Mesh(selection) => session.debug_mesh(selection)?,
    };
    let collected = (|| {
        if trace.event_id != event {
            return Err("Debug trace belongs to another event".to_owned());
        }
        let mut states = Vec::new();
        loop {
            let batch = session.debug_next()?;
            if batch.event_id != event {
                return Err("Debug states belong to another event".to_owned());
            }
            states.extend(batch.states);
            if batch.finished {
                break;
            }
        }
        Ok(ShaderDebugView {
            context,
            trace,
            states,
            navigator: DebugNavigator::default(),
            disassembly: shader.disassembly,
            source_files: shader.source_files,
        })
    })();
    let stopped = session.debug_stop();
    match (collected, stopped) {
        (Ok(view), Ok(())) => Ok(view),
        (Err(error), _) | (_, Err(error)) => Err(error),
    }
}

