#[derive(Default)]
struct TimelineView {
    model: renderdocx::timeline::Timeline,
    shown: bool,
    start: u32,
    end: u32,
    collapsed: std::collections::HashSet<usize>,
    pending_scrub: Option<usize>,
    drag_x: Option<f32>,
    usage: Option<renderdocx::replay::TimelineUsage>,
    history: Option<renderdocx::replay::TimelineHistory>,
}
impl TimelineView {
    fn reset(&mut self, actions: &[renderdocx::replay::Action]) {
        self.model = renderdocx::timeline::Timeline::from_actions(actions);
        self.start = 0;
        self.end = self.model.max_event;
        self.collapsed.clear();
        self.pending_scrub = None;
        self.drag_x = None;
        self.usage = None;
        self.history = None;
    }
    fn zoom(&mut self, inward: bool, focus: Option<u32>) {
        let total = u64::from(self.model.max_event) + 1;
        let length = u64::from(self.end) - u64::from(self.start) + 1;
        let next = if inward {
            (length / 2).max(1)
        } else {
            length.saturating_mul(2).min(total)
        };
        let center = focus
            .filter(|id| *id >= self.start && *id <= self.end)
            .map(u64::from)
            .unwrap_or(u64::from(self.start) + length / 2);
        let start = center.saturating_sub(next / 2).min(total - next);
        self.start = start as u32;
        self.end = (start + next - 1) as u32;
    }
    fn zoom_at(&mut self, steps: f32, anchor: f32) {
        if !steps.is_finite() || !anchor.is_finite() || steps == 0.0 {
            return;
        }
        let total = u64::from(self.model.max_event) + 1;
        let length = u64::from(self.end) - u64::from(self.start) + 1;
        let factor = 1.048_f64.powf(f64::from(steps).clamp(-200.0, 200.0));
        let mut next = ((length as f64 / factor).round() as u64).clamp(1, total);
        if next == length {
            next = if steps > 0.0 {
                length.saturating_sub(1).max(1)
            } else {
                length.saturating_add(1).min(total)
            };
        }
        let anchor = f64::from(anchor.clamp(0.0, 1.0));
        let focal = f64::from(self.start) + length as f64 * anchor;
        let start = (focal - next as f64 * anchor)
            .round()
            .clamp(0.0, (total - next) as f64) as u64;
        self.start = start as u32;
        self.end = (start + next - 1) as u32;
    }
    fn pan_pixels(&mut self, delta: f32, width: f32) {
        if !delta.is_finite() || !width.is_finite() || width <= 0.0 {
            return;
        }
        let total = u64::from(self.model.max_event) + 1;
        let length = u64::from(self.end) - u64::from(self.start) + 1;
        let offset = f64::from(delta) / f64::from(width) * length as f64;
        let start = (f64::from(self.start) - offset)
            .round()
            .clamp(0.0, (total - length) as f64) as u64;
        self.start = start as u32;
        self.end = (start + length - 1) as u32;
    }
    fn pan(&mut self, forward: bool) {
        let total = u64::from(self.model.max_event) + 1;
        let length = u64::from(self.end) - u64::from(self.start) + 1;
        let step = (length / 2).max(1);
        let start = if forward {
            u64::from(self.start)
                .saturating_add(step)
                .min(total - length)
        } else {
            u64::from(self.start).saturating_sub(step)
        };
        self.start = start as u32;
        self.end = (start + length - 1) as u32;
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum MeshBufferKind {
    Vertex,
    Index,
    Draw,
}

struct MeshView {
    selection: MeshSelection,
    kind: MeshBufferKind,
    info: Option<MeshInfo>,
    bytes: Option<Vec<u8>>,
    draw: Option<renderdocx::mesh_draw::DrawPage>,
    filter: renderdocx::mesh_draw::MeshFilter,
    task_sizes: Vec<[u32; 3]>,
    offset: u64,
}

impl Default for MeshView {
    fn default() -> Self {
        Self {
            selection: MeshSelection {
                instance: 0,
                view: 0,
                stage: 1,
            },
            kind: MeshBufferKind::Vertex,
            info: None,
            bytes: None,
            draw: None,
            filter: renderdocx::mesh_draw::MeshFilter::All,
            task_sizes: Vec::new(),
            offset: 0,
        }
    }
}

fn mesh_position_format(info: &MeshInfo) -> bool {
    renderdocx::mesh_positions::supported(info) && u64::from(info.vertex_stride) <= BUFFER_VIEW_PAGE
}

fn mesh_page_size(info: &MeshInfo) -> u64 {
    if info.stage == 3
        && info.vertex_stride > 0
        && info.vertex_stride <= renderdocx::replay::BUFFER_PAGE_LIMIT
    {
        let stride = u64::from(info.vertex_stride);
        (BUFFER_VIEW_PAGE / stride)
            .max(1)
            .min(u64::from(renderdocx::task_payload::PAGE_LIMIT))
            * stride
    } else if mesh_position_format(info) {
        BUFFER_VIEW_PAGE / u64::from(info.vertex_stride) * u64::from(info.vertex_stride)
    } else {
        BUFFER_VIEW_PAGE
    }
}

#[cfg(test)]
fn mesh_indices(info: &MeshInfo, bytes: &[u8], offset: u64) -> Option<Vec<(u64, u32)>> {
    renderdocx::mesh_indices::decode(info, bytes, offset)?
        .into_iter()
        .map(|index| Some((index.row.parse().ok()?, index.raw)))
        .collect()
}

fn mesh_index_page_len(info: &MeshInfo, offset: u64) -> u64 {
    let total = (u64::from(info.num_indices) * u64::from(info.index_stride))
        .min(info.index_size.parse::<u64>().unwrap_or(0));
    total.saturating_sub(offset).min(BUFFER_VIEW_PAGE)
}

fn mesh_positions(info: &MeshInfo, bytes: &[u8], offset: u64) -> Option<Vec<(u64, Vec<f32>)>> {
    if !mesh_position_format(info) {
        return None;
    }
    renderdocx::mesh_positions::decode(info, bytes, offset)?
        .into_iter()
        .map(|position| Some((position.row.parse().ok()?, position.values)))
        .collect()
}

#[cfg(test)]
mod mesh_tests {
    use super::*;

    #[test]
    fn position_pages_preserve_vertices_when_stride_does_not_divide_page() {
        let info = MeshInfo {
            vertex_stride: 20,
            component_type: 1,
            component_count: 4,
            component_byte_width: 4,
            unproject: true,
            ..MeshInfo::default()
        };
        assert_eq!(mesh_page_size(&info), 240);
        let mut bytes = Vec::new();
        for n in 0..24 {
            for value in [n as f32, 3.0, 0.0, 1.0] {
                bytes.extend(value.to_le_bytes());
            }
            bytes.extend([0; 4]);
        }
        let first = mesh_positions(&info, &bytes[..240], 0).unwrap();
        let second = mesh_positions(&info, &bytes[240..], 240).unwrap();
        assert_eq!(first.len(), 12);
        assert_eq!(second.len(), 12);
        assert_eq!(first[11].0, 11);
        assert_eq!(second[0], (12, vec![12.0, 3.0, 0.0, 1.0]));
        let unprojected = MeshInfo {
            unproject: false,
            ..info.clone()
        };
        assert_eq!(
            mesh_positions(&unprojected, &bytes[..240], 0).unwrap(),
            first
        );
        let unsupported = MeshInfo {
            vertex_stride: 512,
            ..info
        };
        assert!(mesh_positions(&unsupported, &bytes, 0).is_none());
        assert_eq!(mesh_page_size(&unsupported), BUFFER_VIEW_PAGE);
    }

    #[test]
    fn indices_decode_all_supported_widths_and_preserve_offsets() {
        let mut info = MeshInfo {
            index_stride: 1,
            ..Default::default()
        };
        assert_eq!(
            mesh_indices(&info, &[2, 255], 0).unwrap(),
            [(0, 2), (1, 255)]
        );
        info.index_stride = 2;
        assert_eq!(
            mesh_indices(&info, &[1, 0, 255, 255], 4).unwrap(),
            [(2, 1), (3, 65535)]
        );
        assert!(mesh_indices(&info, &[1], 0).is_none());
        assert!(mesh_indices(&info, &[1, 0], 1).is_none());
        info.index_stride = 4;
        assert_eq!(
            mesh_indices(&info, &[0xff, 0xff, 0xff, 0xff], 0).unwrap(),
            [(0, u32::MAX)]
        );
        info.index_stride = 3;
        assert!(mesh_indices(&info, &[0; 3], 0).is_none());
        info.index_stride = 2;
        info.num_indices = 300;
        info.index_size = "270".into();
        assert_eq!(mesh_index_page_len(&info, 0), BUFFER_VIEW_PAGE);
        assert_eq!(mesh_index_page_len(&info, BUFFER_VIEW_PAGE), 14);
        assert_eq!(mesh_index_page_len(&info, 270), 0);
    }
}

#[cfg(test)]
mod pixel_selector_tests {
    use super::parse_optional_debug_selector;
    #[test]
    fn blank_means_default_and_reserved_or_invalid_values_are_rejected() {
        assert_eq!(parse_optional_debug_selector(" "), Ok(None));
        assert_eq!(parse_optional_debug_selector(" 42 "), Ok(Some(42)));
        assert_eq!(
            parse_optional_debug_selector("4294967294"),
            Ok(Some(u32::MAX - 1))
        );
        assert!(parse_optional_debug_selector("4294967295").is_err());
        assert!(parse_optional_debug_selector("-1").is_err());
        assert!(parse_optional_debug_selector("4294967296").is_err());
    }
}

#[cfg(test)]
mod shader_source_tests {
    use super::shader_source_page;
    #[test]
    fn source_pages_preserve_unicode_and_line_numbers() {
        let source = (1..=205).map(|i| format!("第{i}行\n")).collect::<String>();
        let (total, first) = shader_source_page(&source, 0);
        assert_eq!(total, 205);
        assert_eq!(first.len(), 200);
        assert_eq!(first[0], (1, "第1行"));
        let (_, last) = shader_source_page(&source, 1);
        assert_eq!(last.len(), 5);
        assert_eq!(last[0], (201, "第201行"));
        assert!(shader_source_page(&source, usize::MAX).1.is_empty());
        assert_eq!(shader_source_page("", 0).0, 0);
    }
}

fn structured_value(node: &StructuredNode) -> String {
    match (&node.custom_string, &node.value) {
        (Some(custom), Some(value)) if custom != value => format!("{custom} ({value})"),
        (Some(custom), _) => custom.clone(),
        (_, Some(value)) => value.clone(),
        _ if node.basic_type == 3
            || node.flags & 8 != 0
            || node.resource_non_null == Some(false) =>
        {
            "NULL".into()
        }
        _ if node.resource_non_null == Some(true) => node
            .resource_index
            .map(|index| format!("#{index}"))
            .unwrap_or_default(),
        _ => String::new(),
    }
}

