        let index_buffer_label = self.t(
            "Index buffer",
            "索引缓冲区",
            "インデックスバッファ",
            "인덱스 버퍼",
        );
        let inputs_label = self.t("Vertex inputs", "顶点输入", "頂点入力", "정점 입력");
        let viewport_label = self.t("Viewports", "视口", "ビューポート", "뷰포트");
        let scissor_label = self.t("Scissors", "裁剪矩形", "シザー矩形", "시저 사각형");
